#!/bin/sh
# review-diff.sh — review a branch diff without pulling all of it into context.
#
# Usage: review-diff.sh <repo> <base> [<head>]            → the review plan
#        review-diff.sh <repo> <base> [<head>] --file <path> → one file's diff
#   base/head  refs (default head: HEAD); compared as <base>...<head>, i.e.
#              only what the branch changed since it left <base>
#
# The plan lists every changed file with its +/- counts, split into
#   review:  files to read one at a time with --file
#   skip:    task workspace files (work/, evidence/), files generated by this
#            framework's build_copilot.py, lockfiles and minified bundles —
#            listed so their presence is visible, but not worth reading
# Reviewers (code-reviewer, scope-auditor) start here and open files one by
# one; nothing in "review" may be left unread, and a "skip" entry that should
# not be in the diff at all is itself a finding.
set -eu

REPO="${1:?usage: review-diff.sh <repo> <base> [<head>] [--file <path>]}"
BASE="${2:?usage: review-diff.sh <repo> <base> [<head>] [--file <path>]}"
shift 2
HEAD_REF=HEAD
FILE=""
while [ $# -gt 0 ]; do
  case "$1" in
    --file) FILE="${2:?--file needs a path}"; shift 2 ;;
    -*) echo "error: unknown option $1" >&2; exit 2 ;;
    *) HEAD_REF=$1; shift ;;
  esac
done
git -C "$REPO" rev-parse --verify -q "$BASE^{commit}" >/dev/null || { echo "error: base ref '$BASE' not found in $REPO" >&2; exit 2; }
git -C "$REPO" rev-parse --verify -q "$HEAD_REF^{commit}" >/dev/null || { echo "error: head ref '$HEAD_REF' not found in $REPO" >&2; exit 2; }
RANGE="$BASE...$HEAD_REF"

if [ -n "$FILE" ]; then
  git -C "$REPO" diff --no-color -U5 "$RANGE" -- "$FILE"
  exit 0
fi

MARKER="generated by software-engineer-stack scripts/build_copilot.py"
is_skip() {  # is_skip <path> — prints the reason, or nothing
  case "$1" in
    work/*|*/work/*) echo "task workspace"; return ;;
    evidence/*|*/evidence/*) echo "evidence"; return ;;
    *.lock|package-lock.json|*/package-lock.json|*.min.js|*.min.css) echo "lockfile/minified"; return ;;
  esac
  if git -C "$REPO" show "$HEAD_REF:$1" 2>/dev/null | head -n 5 | grep -q "$MARKER"; then
    echo "framework-generated"
  fi
}

TOTAL=$(git -C "$REPO" diff --no-renames --shortstat "$RANGE" | sed 's/^ *//')
echo "diff $RANGE in $REPO: ${TOTAL:-no changes}"
REVIEW=""; SKIP=""; NR=0; NS=0
NL='
'
while IFS="$(printf '\t')" read -r add del path; do
  [ -n "$path" ] || continue
  why=$(is_skip "$path")
  line=$(printf '%6s %6s  %s' "+$add" "-$del" "$path")
  if [ -n "$why" ]; then
    SKIP="$SKIP$line  ($why)$NL"; NS=$((NS + 1))
  else
    REVIEW="$REVIEW$line$NL"; NR=$((NR + 1))
  fi
done <<EOF
$(git -C "$REPO" diff --no-renames --numstat "$RANGE")
EOF

echo "review: $NR file(s) — read each with: review-diff.sh $REPO $BASE $HEAD_REF --file <path>"
printf '%s' "$REVIEW"
if [ "$NS" -gt 0 ]; then
  echo "skip: $NS file(s) — not read; flag any that should not be in this diff at all"
  printf '%s' "$SKIP"
fi
